(async()=>{const d=document.documentElement;d.classList.remove('dark');d.style.colorScheme='light';const vis=(s)=>[...document.querySelectorAll(s)].find(e=>e.getBoundingClientRect().height>0)||null;const nap=(ms)=>new Promise(r=>setTimeout(r,ms));
let el=null;for(let i=0;i<60;i++){el=vis('[data-design-focus="inbound-surfaces"]');if(el)break;await nap(200)}
if(!el)return 'MISS: inbound-surfaces never rendered';
const on=[...document.querySelectorAll('[role=switch]')].filter(s=>['WhatsApp','SMS'].includes(s.getAttribute('aria-label'))&&s.getBoundingClientRect().height>0&&s.getAttribute('aria-checked')==='true');
on.forEach(s=>{s.click();s.blur()});
try{localStorage.setItem('sx:channel_demand','[]')}catch(e){}
await nap(400);
el.scrollIntoView({block:'center'});
await nap(500);
el.style.outline='';el.style.outlineOffset='';
el.setAttribute('data-shot18','surfaces');
const b=el.getBoundingClientRect();
return 'surfaces '+[b.x|0,b.y|0,b.width|0,b.height|0].join(',');})()

(async()=>{const d=document.documentElement;d.classList.remove('dark');d.style.colorScheme='light';const vis=(s)=>[...document.querySelectorAll(s)].find(e=>e.getBoundingClientRect().height>0)||null;const nap=(ms)=>new Promise(r=>setTimeout(r,ms));
let sw=null;for(let i=0;i<60;i++){sw=[...document.querySelectorAll('[role=switch]')].find(s=>s.getAttribute('aria-label')==='WhatsApp'&&s.getBoundingClientRect().height>0);if(sw)break;await nap(200)}
if(!sw)return 'MISS: WhatsApp switch never rendered';
if(sw.getAttribute('aria-checked')==='false'){sw.click();sw.blur()}
await nap(500);
const door=[...document.querySelectorAll('button')].find(b=>b.textContent.trim()==='See what each channel needs'&&b.getBoundingClientRect().height>0);
if(!door)return 'MISS: sheet door';
door.click();
let row=null;for(let i=0;i<60;i++){row=vis('#ch-whatsapp');if(row)break;await nap(150)}
if(!row)return 'MISS: sheet row';
row.setAttribute('data-shot18','wa-sheet');
await nap(400);
const b=row.getBoundingClientRect();
return 'sheet row '+[b.x|0,b.y|0,b.width|0,b.height|0].join(',')+' asked='+row.querySelector('[role=switch]').getAttribute('aria-checked');})()

(async()=>{const d=document.documentElement;d.classList.remove('dark');d.style.colorScheme='light';const vis=(s)=>[...document.querySelectorAll(s)].find(e=>e.getBoundingClientRect().height>0)||null;const nap=(ms)=>new Promise(r=>setTimeout(r,ms));
let row=null;
for(let i=0;i<60;i++){row=[...document.querySelectorAll('tbody tr')].find(r=>{const c=r.querySelector('td');return c&&/^WhatsApp/.test(c.innerText.trim())&&r.getBoundingClientRect().height>0});if(row)break;await nap(200)}
if(!row)return 'MISS: WhatsApp inventory row';
row.setAttribute('data-shot18','wa-row');
row.scrollIntoView({block:'center'});
await nap(500);
const b=row.getBoundingClientRect();
return 'row '+[b.x|0,b.y|0,b.width|0,b.height|0].join(',')+' · '+row.innerText.replace(/[\s]+/g,' ').slice(0,60);})()
